import{_ as o,a}from"./chunks/screenshot-client.BBcQFa0Y.js";import{_ as r,o as i,c as l,a1 as s}from"./chunks/framework.DQ_lpCRI.js";const b=JSON.parse('{"title":"Android App 使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/android.md","filePath":"zh/guide/android.md"}'),e={name:"zh/guide/android.md"};function n(d,t,h,g,p,c){return i(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="android-app-使用指南" tabindex="-1">Android App 使用指南 <a class="header-anchor" href="#android-app-使用指南" aria-label="Permalink to &quot;Android App 使用指南&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Android 应用提供两种模式：<strong>Host</strong>（分享你的连接）和 <strong>Client</strong>（连接到其他主机）。</p><p><img src="'+o+'" alt="Hotspot Bypass VPN App"></p><hr><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>从<a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/zh/download">下载页面</a>获取最新 APK。</li><li>在手机上打开 APK 文件。</li><li>如提示，请启用<strong>允许安装未知来源应用</strong>。</li><li>完成安装。</li></ol><hr><h2 id="host-模式-分享你的连接" tabindex="-1">Host 模式（分享你的连接） <a class="header-anchor" href="#host-模式-分享你的连接" aria-label="Permalink to &quot;Host 模式（分享你的连接）&quot;">​</a></h2><p>使用此模式将手机蜂窝数据分享给其他设备。</p><p><img src="'+o+'" alt="Host 模式截图"><em>Host 模式显示连接信息</em></p><h3 id="第一步-授予权限" tabindex="-1">第一步：授予权限 <a class="header-anchor" href="#第一步-授予权限" aria-label="Permalink to &quot;第一步：授予权限&quot;">​</a></h3><p>首次点击 <strong>启动 Host</strong> 时，应用会请求：</p><ul><li><strong>位置权限</strong> — Android 要求 Wi-Fi Direct 发现需要此权限</li><li><strong>通知权限</strong> — 前台服务需要</li><li><strong>忽略电池优化</strong> — 防止系统杀死服务</li></ul><p>请授予所有权限以获得最佳体验。</p><h3 id="第二步-配置设置" tabindex="-1">第二步：配置设置 <a class="header-anchor" href="#第二步-配置设置" aria-label="Permalink to &quot;第二步：配置设置&quot;">​</a></h3><p>开始之前，可以配置：</p><ul><li><strong>Wi-Fi 频段</strong> — 选择 2.4GHz（更远距离）或 5GHz（更低延迟，推荐游戏使用）</li><li>检查<strong>私有 DNS</strong> 设置为<strong>关闭</strong>或<strong>自动</strong>（不是自定义 DNS 提供商）</li></ul><h3 id="第三步-启动-host" tabindex="-1">第三步：启动 Host <a class="header-anchor" href="#第三步-启动-host" aria-label="Permalink to &quot;第三步：启动 Host&quot;">​</a></h3><ol><li>点击顶部的 <strong>HOST</strong> 标签。</li><li>点击 <strong>启动 Host</strong>。</li><li>出现通知：<strong>&quot;Hotspot Bypass Host&quot;</strong> — 确认服务正在运行。</li><li>屏幕会显示连接详情： <ul><li><strong>SSID：</strong> <code>DIRECT-HotspotBypass</code></li><li><strong>密码：</strong> <code>87654321</code></li><li><strong>代理 IP：</strong> <code>192.168.49.1</code></li><li><strong>代理端口：</strong> <code>8080</code></li></ul></li><li>点击每个字段旁的<strong>复制图标</strong>分享给客户端。</li></ol><h3 id="第四步-客户端设备连接" tabindex="-1">第四步：客户端设备连接 <a class="header-anchor" href="#第四步-客户端设备连接" aria-label="Permalink to &quot;第四步：客户端设备连接&quot;">​</a></h3><p>告知客户端：</p><ol><li>打开设备的 Wi-Fi 设置。</li><li>连接到网络 <strong>DIRECT-HotspotBypass</strong>。</li><li>输入密码 <strong>87654321</strong>。</li><li>配置设备或应用使用 SOCKS5 代理 <code>192.168.49.1:8080</code>。</li></ol><hr><h2 id="client-模式-连接到-host" tabindex="-1">Client 模式（连接到 Host） <a class="header-anchor" href="#client-模式-连接到-host" aria-label="Permalink to &quot;Client 模式（连接到 Host）&quot;">​</a></h2><p>当其他手机在 Host 模式下运行时，使用此模式连接。</p><p><img src="'+a+'" alt="Client 模式截图"><em>Client 模式显示 VPN 已连接状态</em></p><h3 id="第一步-授予权限-1" tabindex="-1">第一步：授予权限 <a class="header-anchor" href="#第一步-授予权限-1" aria-label="Permalink to &quot;第一步：授予权限&quot;">​</a></h3><p>与 Host 模式类似，应用会请求位置、通知和电池优化权限。</p><h3 id="第二步-连接" tabindex="-1">第二步：连接 <a class="header-anchor" href="#第二步-连接" aria-label="Permalink to &quot;第二步：连接&quot;">​</a></h3><ol><li>点击顶部的 <strong>CLIENT</strong> 标签。</li><li>点击 <strong>启动 Client</strong>。</li><li>应用将： <ul><li>扫描 Wi-Fi Direct 网络</li><li>连接到 Host 的网络</li><li>启动本地 VPN，将所有流量通过 Host 的 SOCKS5 代理隧道转发</li></ul></li><li>出现 VPN 通知：<strong>&quot;Hotspot Bypass VPN&quot;</strong></li></ol><h3 id="第三步-验证" tabindex="-1">第三步：验证 <a class="header-anchor" href="#第三步-验证" aria-label="Permalink to &quot;第三步：验证&quot;">​</a></h3><ul><li>打开浏览器 — 流量现在应通过 Host 的连接路由。</li><li>查看调试日志（屏幕底部可展开区域）了解连接状态。</li></ul><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>解决方案</th></tr></thead><tbody><tr><td>找不到 Host 网络</td><td>确保两台设备都启用了 Wi-Fi Direct。尝试关闭/重新打开 Wi-Fi。</td></tr><tr><td>VPN 连接失败</td><td>点击<strong>重新连接 VPN</strong>按钮。如果仍然不行，请重启应用。</td></tr><tr><td>速度慢</td><td>尝试在 Host 端切换到 5GHz 频段。确保设备间信号良好。</td></tr><tr><td>私有 DNS 警告</td><td>进入设置 → 网络和互联网 → 私有 DNS → 设置为<strong>关闭</strong>或<strong>自动</strong>。</td></tr><tr><td>锁屏后服务停止</td><td>授予应用<strong>忽略电池优化</strong>权限。</td></tr><tr><td>连接断开</td><td>两台设备应保持在 Wi-Fi Direct 范围内（通常 30-50 米）。</td></tr></tbody></table><hr><h2 id="调试日志" tabindex="-1">调试日志 <a class="header-anchor" href="#调试日志" aria-label="Permalink to &quot;调试日志&quot;">​</a></h2><p>应用内置调试日志查看器，位于屏幕底部。点击展开即可查看实时诊断信息，帮助排查连接问题。</p>',38)])])}const q=r(e,[["render",n]]);export{b as __pageData,q as default};
